-- Kiwar: full database setup for a NEW Supabase project (generated by `pnpm build:sql`).
-- Paste everything into the SQL Editor and click Run. For an existing project, run only
-- the migrations added since your last setup (see docs/SUPABASE_SETUP.md).

-- ===== 20261020000000_init.sql =====

-- Kiwar — milestone 2: server-authoritative games.
-- Players never write their game directly: every write goes through the `game` edge function
-- (service role), which validates commands with the shared rules. Players can only read.

create table public.games (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  -- Milestone 2: one solo universe per player ('solo-<user id>'). Milestone 3 adds shared ones.
  universe_id text not null,
  face text not null check (face in ('kiwisu', 'kiwino')),
  state jsonb not null,
  -- Optimistic concurrency token, incremented on every write.
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, universe_id)
);

comment on table public.games is 'Authoritative game states (written by the game edge function only).';

-- Audit trail of every command (anti-cheat, rate limiting, balancing data later).
create table public.command_log (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  game_id uuid references public.games (id) on delete cascade,
  command jsonb not null,
  ok boolean not null,
  error text,
  created_at timestamptz not null default now()
);

create index command_log_user_time on public.command_log (user_id, created_at desc);

-- Accounts allowed to use debug commands on the server.
create table public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade
);

alter table public.games enable row level security;
alter table public.command_log enable row level security;
alter table public.admins enable row level security;

-- Players (guests included: anonymous users are `authenticated`) may read their own games.
create policy "players read their own games"
  on public.games for select
  to authenticated
  using (user_id = (select auth.uid()));

-- No insert/update/delete policy on games, and no policy at all on command_log / admins:
-- only the service role (edge function) can write them.

-- Keep the log small: commands older than 30 days are purged by this helper
-- (schedule it with pg_cron if wanted: select cron.schedule('purge-kiwar-log', '0 4 * * *', 'select public.purge_command_log()')).
create function public.purge_command_log() returns void
  language sql
  security definer
  set search_path = ''
as $$
  delete from public.command_log where created_at < now() - interval '30 days';
$$;

revoke all on function public.purge_command_log() from public, anon, authenticated;

-- ===== 20261021000000_universes_chat.sql =====

-- Kiwar — milestone 3: shared universes and team chat.
-- Universes and memberships are written by the `game` edge function only (it assigns faces).
-- Chat messages are written directly by members, under RLS.

create table public.universes (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 40),
  code text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{8}$'),
  seed text not null,
  created_by uuid references auth.users (id) on delete set null,
  max_players integer not null default 8 check (max_players between 2 and 16),
  -- Player-versus-player raids (later milestones); co-op only for now.
  pvp boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.universe_members (
  universe_id uuid not null references public.universes (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 24),
  kiwi_index integer not null check (kiwi_index >= 0),
  face text not null check (face in ('kiwisu', 'kiwino')),
  joined_at timestamptz not null default now(),
  primary key (universe_id, user_id),
  unique (universe_id, kiwi_index, face)
);

create index universe_members_user on public.universe_members (user_id);

-- Membership test usable in policies without recursive RLS evaluation.
create function public.is_universe_member(target uuid) returns boolean
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select exists (
    select 1 from public.universe_members m
    where m.universe_id = target and m.user_id = (select auth.uid())
  );
$$;

revoke all on function public.is_universe_member(uuid) from public, anon;
grant execute on function public.is_universe_member(uuid) to authenticated;

alter table public.universes enable row level security;
alter table public.universe_members enable row level security;

create policy "members read their universes"
  on public.universes for select to authenticated
  using (public.is_universe_member(id));

create policy "members read the member list"
  on public.universe_members for select to authenticated
  using (public.is_universe_member(universe_id));

-- Team chat ----------------------------------------------------------------

create table public.chat_messages (
  id bigint generated always as identity primary key,
  universe_id uuid not null references public.universes (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  display_name text not null default '',
  body text not null check (char_length(body) between 1 and 280),
  created_at timestamptz not null default now()
);

create index chat_messages_universe_time on public.chat_messages (universe_id, created_at desc);

-- The author name comes from the membership (cannot be spoofed); light flood protection.
create function public.chat_before_insert() returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
declare
  recent integer;
begin
  new.user_id := auth.uid();
  new.created_at := now();
  select m.display_name into new.display_name
    from public.universe_members m
    where m.universe_id = new.universe_id and m.user_id = new.user_id;
  if new.display_name is null then
    raise exception 'not a member of this universe' using errcode = '42501';
  end if;
  select count(*) into recent from public.chat_messages c
    where c.user_id = new.user_id and c.created_at > now() - interval '10 seconds';
  if recent >= 5 then
    raise exception 'slow down' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger chat_before_insert
  before insert on public.chat_messages
  for each row execute function public.chat_before_insert();

alter table public.chat_messages enable row level security;

create policy "members read the chat"
  on public.chat_messages for select to authenticated
  using (public.is_universe_member(universe_id));

create policy "members post in the chat"
  on public.chat_messages for insert to authenticated
  with check (user_id = (select auth.uid()) and public.is_universe_member(universe_id));

-- Reports go to the admins (no read access for players).
create table public.chat_reports (
  id bigint generated always as identity primary key,
  message_id bigint not null references public.chat_messages (id) on delete cascade,
  reporter uuid not null default auth.uid() references auth.users (id) on delete cascade,
  reason text not null default '' check (char_length(reason) <= 200),
  created_at timestamptz not null default now(),
  unique (message_id, reporter)
);

alter table public.chat_reports enable row level security;

create policy "members report messages of their universes"
  on public.chat_reports for insert to authenticated
  with check (
    reporter = (select auth.uid())
    and exists (
      select 1 from public.chat_messages c
      where c.id = message_id and public.is_universe_member(c.universe_id)
    )
  );

-- Live chat through Supabase Realtime (the publication only exists on Supabase).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
end;
$$;

-- ===== 20261022000000_audio.sql =====

-- Chantier 02: audio. Sounds uploaded from the admin space (Storage bucket `audio` + catalogue
-- table) and bindings "sound event → sounds + parameters" read by every client at startup.
-- Everyone (even signed-out visitors) can read; only accounts listed in `admins` can write.

-- True when the caller is listed in `admins` (that table has no read policy on purpose).
create function public.is_admin() returns boolean
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select exists (select 1 from public.admins a where a.user_id = (select auth.uid()));
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- Uploaded sound files (the bytes live in Storage, bucket `audio`, at `path`).
create table public.audio_assets (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 80),
  path text not null unique check (path ~ '^[A-Za-z0-9._/-]{1,200}$'),
  mime text not null
    check (mime in ('audio/mpeg', 'audio/ogg', 'audio/wav', 'audio/x-wav', 'audio/webm', 'audio/mp4')),
  duration_ms integer not null default 0 check (duration_ms between 0 and 600000),
  size_bytes integer not null check (size_bytes between 1 and 2097152),
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

-- One row per sound event overriding the built-in default (e.g. `ui.click`, `music.main`).
-- `binding` holds the parameters (sources, volume, pitch, cooldown…); the client validates it
-- with the same schema as the admin editor and falls back to the default if it is invalid.
create table public.audio_bindings (
  event_id text primary key
    check (char_length(event_id) <= 64 and event_id ~ '^[a-z]+(\.[a-z0-9_-]+)+$'),
  binding jsonb not null
    check (
      jsonb_typeof(binding) = 'object'
      and octet_length(binding::text) <= 8192
      and case jsonb_typeof(binding -> 'sources')
        when 'array' then jsonb_array_length(binding -> 'sources') <= 16
        else binding -> 'sources' is null
      end
    ),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  updated_at timestamptz not null default now()
);

create function public.touch_audio_binding() returns trigger
  language plpgsql
  set search_path = ''
as $$
begin
  new.updated_at := now();
  new.updated_by := (select auth.uid());
  return new;
end;
$$;

create trigger audio_bindings_touch
  before update on public.audio_bindings
  for each row execute function public.touch_audio_binding();

alter table public.audio_assets enable row level security;
alter table public.audio_bindings enable row level security;

create policy "everyone reads audio assets"
  on public.audio_assets for select to anon, authenticated
  using (true);

create policy "admins add audio assets"
  on public.audio_assets for insert to authenticated
  with check (public.is_admin());

create policy "admins edit audio assets"
  on public.audio_assets for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy "admins remove audio assets"
  on public.audio_assets for delete to authenticated
  using (public.is_admin());

create policy "everyone reads audio bindings"
  on public.audio_bindings for select to anon, authenticated
  using (true);

create policy "admins add audio bindings"
  on public.audio_bindings for insert to authenticated
  with check (public.is_admin());

create policy "admins edit audio bindings"
  on public.audio_bindings for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy "admins remove audio bindings"
  on public.audio_bindings for delete to authenticated
  using (public.is_admin());

-- Storage bucket: public read (files are served by URL), 2 MB per file, audio types only.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'audio',
  'audio',
  true,
  2097152,
  array['audio/mpeg', 'audio/ogg', 'audio/wav', 'audio/x-wav', 'audio/webm', 'audio/mp4']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy "everyone reads audio files"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'audio');

create policy "admins upload audio files"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'audio' and public.is_admin());

create policy "admins replace audio files"
  on storage.objects for update to authenticated
  using (bucket_id = 'audio' and public.is_admin())
  with check (bucket_id = 'audio' and public.is_admin());

create policy "admins delete audio files"
  on storage.objects for delete to authenticated
  using (bucket_id = 'audio' and public.is_admin());

-- ===== 20261024000000_hide_game_state.sql =====

-- Chantier 07: stored games hold the real alien garrisons, which players must never see (they
-- only get what their reconnaissance missions report). The game function (service role) is the
-- only reader and writer of games: players no longer read their rows directly.
drop policy if exists "players read their own games" on public.games;
